pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address addr1, address addr2, uint256 amount1, uint256 amount2) public {
        amount1 = bound(amount1, 0, 1e18);
        amount2 = bound(amount2, 0, 1e18);
        vm.assume(addr1 != address(0) && addr2 != address(0) && addr1 != addr2);

        // Deposit from addr1
        vm.deal(addr1, amount1);
        vm.prank(addr1);
        c.deposit{value: amount1}();

        // Deposit from addr2
        vm.deal(addr2, amount2);
        vm.prank(addr2);
        c.deposit{value: amount2}();

        // Withdraw all from addr1
        vm.prank(addr1);
        c.withdrawAll();

        // Now claim: contract balance >= credit[addr2] (addr2's credit after addr1 withdrew)
        // The invariant: total deposits = contract balance + withdrawn amounts
        // Simpler: after all operations, contract.balance = credit[addr2] (since addr1 credit is 0)
        assertTrue(address(c).balance == c.credit(addr2));
    }
}

